// One item per tracked product: pull today's price out of the page, compare it with the last one.
const out = [];
for (const item of $input.all()) {
  const html = String(item.json.data || '');
  const row = $('Your tracked products are read').item.json;
  let price = null;

  // Most shops publish the price in a schema.org block in the page source. Same parser for every store.
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/g)) {
    try {
      const blocks = [].concat(JSON.parse(m[1].trim()));
      for (const b of blocks) {
        const offer = [].concat(b.offers || [])[0];
        if (offer && offer.price) price = Number(String(offer.price).replace(/[^0-9.,]/g, '').replace(',', '.'));
      }
    } catch (e) { /* not the block we are after, keep looking */ }
  }

  // Fallback for shops without it. A shop that hides the price behind JavaScript gets its own rule here.
  if (price === null) {
    const meta = html.match(/itemprop=["']price["'][^>]*content=["']([0-9.,]+)["']/i)
      || html.match(/property=["']product:price:amount["'][^>]*content=["']([0-9.,]+)["']/i);
    if (meta) price = Number(meta[1].replace(',', '.'));
  }

  const last = Number(row.last_price || 0);
  const target = Number(row.target_price || 0);
  out.push({ json: {
    product: row.product,
    store: row.store,
    url: row.url,
    price,
    last_price: last || price,
    target_price: target,
    dropped: price !== null && last > 0 && price < last,
    hit_target: price !== null && target > 0 && price <= target,
    unreadable: price === null,
    checked_at: $now.toFormat('yyyy-MM-dd HH:mm')
  }});
}
return out;

