// The same product in four stores becomes four rows, so each one is checked on its own.
const rows = [];
for (const item of $input.all()) {
  const product = item.json['What is it?'];
  const target = item.json['Tell me when it drops below'] || '';
  const links = String(item.json['Product links, one per line'] || '')
    .split('\n').map(l => l.trim()).filter(Boolean);
  for (const url of links) {
    let store = '';
    try { store = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { continue; }
    rows.push({ json: { product, store, url, target_price: target, last_price: '', last_checked: '', status: 'new' } });
  }
}
return rows;
